package busmate;

import com.google.gson.*;
import com.sun.net.httpserver.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.sql.*;import java.util.*;import java.util.concurrent.*;

public class BusMateServer {
 static final String DB_URL="jdbc:mysql://localhost:3306/busmate_fresh?serverTimezone=Asia/Kolkata";
 static final String DB_USER=System.getenv().getOrDefault("BUSMATE_DB_USER","root"), DB_PASSWORD=System.getenv("BUSMATE_DB_PASSWORD");
 static final String ADMIN_EMAIL="hariini2526@gmail.com", ADMIN_PASSWORD=System.getenv("BUSMATE_ADMIN_PASSWORD");
 static final Gson G=new Gson();
 static final SecureRandom RNG=new SecureRandom();
 static final Map<String,Sess> SESS=new ConcurrentHashMap<>();
 // Finds the project root whether Maven is started from BusMate/ or BusMate/backend/.
 static final Path ROOT = findProjectRoot();
 static Path findProjectRoot() {
   Path cwd = Paths.get("").toAbsolutePath().normalize();
   Path[] candidates = new Path[] { cwd, cwd.getParent(), cwd.resolve("..").normalize(), cwd.resolve("../..").normalize() };
   for (Path p : candidates) if (p != null && Files.isRegularFile(p.resolve("home.html"))) return p;
   return cwd;
 }
 record Sess(int id,String email,String role,String name){}
 static Connection db() throws SQLException {if(DB_PASSWORD==null||DB_PASSWORD.isBlank())throw new SQLException("Set BUSMATE_DB_PASSWORD in this terminal first.");return DriverManager.getConnection(DB_URL,DB_USER,DB_PASSWORD);}
 static String hash(String s)throws Exception{byte[] b=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder x=new StringBuilder();for(byte v:b)x.append(String.format("%02x",v&255));return x.toString();}
 static void json(HttpExchange e,int code,Object o)throws IOException{byte[] b=G.toJson(o).getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","application/json; charset=UTF-8");e.getResponseHeaders().set("Cache-Control","no-store");e.getResponseHeaders().set("X-Content-Type-Options","nosniff");e.sendResponseHeaders(code,b.length);try(OutputStream out=e.getResponseBody()){out.write(b);}}
 static Map<String,Object> body(HttpExchange e)throws IOException{byte[] b=e.getRequestBody().readAllBytes();if(b.length>100000)throw new IOException("Request too large");Map<String,Object> m=G.fromJson(new String(b,StandardCharsets.UTF_8),Map.class);return m==null?new HashMap<>():m;}
 static String str(Map<?, ?> m, String k) { Object v = m.get(k); return v == null ? "" : String.valueOf(v).trim(); }
 static int num(Map<?, ?> m, String k, int def) { try { return (int) Double.parseDouble(str(m, k)); } catch (Exception e) { return def; } }
 static boolean bool(Map<?, ?> m, String k) { Object v = m.get(k); return Boolean.TRUE.equals(v) || "true".equalsIgnoreCase(String.valueOf(v)) || "1".equals(String.valueOf(v)); }
 static Map<String,String> query(String raw){Map<String,String> m=new HashMap<>();if(raw!=null)for(String p:raw.split("&")){String[] a=p.split("=",2);try{m.put(URLDecoder.decode(a[0],"UTF-8"),URLDecoder.decode(a.length>1?a[1]:"","UTF-8"));}catch(Exception ignored){}}return m;}
 static String cookie(HttpExchange e){List<String> h=e.getRequestHeaders().get("Cookie");if(h!=null)for(String line:h)for(String p:line.split(";")){String[] a=p.trim().split("=",2);if(a.length==2&&a[0].equals("BUSMATE_SESSION"))return a[1];}return null;}
 static Sess session(HttpExchange e){String t=cookie(e);return t==null?null:SESS.get(t);} static boolean role(HttpExchange e,String r)throws IOException{Sess s=session(e);if(s==null){json(e,401,Map.of("message","Please sign in again."));return false;}if(!s.role.equals(r)){json(e,403,Map.of("message","Access denied."));return false;}return true;}
 static List<Map<String,Object>> rows(String sql,Object... args)throws SQLException{try(Connection c=db();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);try(ResultSet r=p.executeQuery()){List<Map<String,Object>> out=new ArrayList<>();ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object> m=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++){Object v=r.getObject(i);if(v instanceof java.sql.Time)v=v.toString();if(v instanceof java.sql.Timestamp)v=v.toString();m.put(md.getColumnLabel(i),v);}out.add(m);}return out;}}}
 static int update(String sql,Object...args)throws SQLException{try(Connection c=db();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);return p.executeUpdate();}}
 static int insert(String sql,Object...args)throws SQLException{try(Connection c=db();PreparedStatement p=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS)){for(int i=0;i<args.length;i++)p.setObject(i+1,args[i]);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){return r.next()?r.getInt(1):0;}}}
 static void login(HttpExchange e)throws Exception{if(!e.getRequestMethod().equals("POST")){json(e,405,Map.of("message","POST required"));return;}Map<String,Object> b=body(e);String role=str(b,"role").toUpperCase(),email=str(b,"email").toLowerCase(),pw=str(b,"password");if(!Set.of("STUDENT","DRIVER","ADMIN").contains(role)){json(e,400,Map.of("message","Choose a valid role."));return;}Sess s=null;
  if(role.equals("ADMIN")){if(ADMIN_PASSWORD==null||ADMIN_PASSWORD.isBlank()){json(e,500,Map.of("message","Set BUSMATE_ADMIN_PASSWORD before starting the server."));return;}if(email.equals(ADMIN_EMAIL)&&MessageDigest.isEqual(hash(pw).getBytes(),hash(ADMIN_PASSWORD).getBytes())){List<Map<String,Object>> a=rows("SELECT admin_id,full_name FROM admins WHERE email=? AND active=1",email);if(!a.isEmpty())s=new Sess(((Number)a.get(0).get("admin_id")).intValue(),email,role,String.valueOf(a.get(0).get("full_name")));}}
  else {String table=role.equals("STUDENT")?"students":"drivers",id=role.equals("STUDENT")?"student_id":"driver_id";if(role.equals("STUDENT")&&!email.endsWith("@rajalakshmi.edu.in")){json(e,401,Map.of("message","Use your college email ending in @rajalakshmi.edu.in."));return;}List<Map<String,Object>> a=rows("SELECT "+id+" AS id,full_name,email,password_hash FROM "+table+" WHERE email=? AND active=1",email);if(!a.isEmpty()&&MessageDigest.isEqual(hash(pw).getBytes(),String.valueOf(a.get(0).get("password_hash")).getBytes()))s=new Sess(((Number)a.get(0).get("id")).intValue(),email,role,String.valueOf(a.get(0).get("full_name")));}
  if(s==null){json(e,401,Map.of("message","Invalid email, password, or role."));return;}String old=cookie(e);if(old!=null)SESS.remove(old);byte[] t=new byte[32];RNG.nextBytes(t);String token=Base64.getUrlEncoder().withoutPadding().encodeToString(t);SESS.put(token,s);e.getResponseHeaders().add("Set-Cookie","BUSMATE_SESSION="+token+"; Path=/; HttpOnly; SameSite=Strict");json(e,200,Map.of("message","Login successful","role",s.role,"name",s.name,"email",s.email)); }
 static void logout(HttpExchange e)throws IOException{String t=cookie(e);if(t!=null)SESS.remove(t);e.getResponseHeaders().add("Set-Cookie","BUSMATE_SESSION=; Path=/; Max-Age=0; HttpOnly; SameSite=Strict");json(e,200,Map.of("message","Logged out"));}
 static void api(HttpExchange e)throws Exception{String path=e.getRequestURI().getPath(),method=e.getRequestMethod();Map<String,String> q=query(e.getRequestURI().getRawQuery());if(path.equals("/api/health")){try(Connection c=db()){json(e,200,Map.of("status","OK","database","connected","message","BusMate backend and MySQL are connected."));}return;}if(path.equals("/api/login")){login(e);return;}if(path.equals("/api/logout")){logout(e);return;}if(path.equals("/api/me")){Sess s=session(e);if(s==null)json(e,401,Map.of("message","Not logged in"));else json(e,200,Map.of("userId",s.id,"email",s.email,"role",s.role,"name",s.name));return;}
  if(path.equals("/api/areas")){json(e,200,Map.of("items",rows("SELECT area_id AS areaId,area_name AS areaName FROM areas WHERE active=1 ORDER BY area_name")));return;}
  if(path.equals("/api/student/profile")){if(!role(e,"STUDENT"))return;Sess s=session(e);List<Map<String,Object>> a=rows("SELECT student_id AS studentId,full_name AS fullName,roll_number AS rollNumber,email FROM students WHERE student_id=? AND active=1",s.id);json(e,200,a.isEmpty()?Map.of():a.get(0));return;}
  if(path.equals("/api/student/buses")){if(!role(e,"STUDENT"))return;int area=num(q,"areaId",0);json(e,200,Map.of("items",rows("SELECT b.bus_id AS busId,b.bus_number AS busNumber,b.bus_name AS busName,b.capacity,COUNT(DISTINCT CASE WHEN bk.booking_status='BOOKED' THEN bk.booking_id END) AS bookedSeats,b.capacity-COUNT(DISTINCT CASE WHEN bk.booking_status='BOOKED' THEN bk.booking_id END) AS availableSeats,GROUP_CONCAT(DISTINCT ar.area_name ORDER BY br.route_order SEPARATOR ', ') AS routeNames,MIN(CASE WHEN br.area_id=? THEN TIME_FORMAT(br.pickup_time,'%H:%i') END) AS pickupTime FROM buses b JOIN bus_routes br ON br.bus_id=b.bus_id AND br.active=1 JOIN areas ar ON ar.area_id=br.area_id LEFT JOIN bookings bk ON bk.bus_id=b.bus_id WHERE b.active=1 AND EXISTS(SELECT 1 FROM bus_routes r WHERE r.bus_id=b.bus_id AND r.area_id=? AND r.active=1) GROUP BY b.bus_id ORDER BY availableSeats DESC,b.bus_number",area,area)));return;}
  if(path.equals("/api/student/bookings")&&method.equals("GET")){if(!role(e,"STUDENT"))return;Sess s=session(e);json(e,200,Map.of("items",rows("SELECT bk.booking_id AS bookingId,b.bus_id AS busId,b.bus_number AS busNumber,bk.seat_number AS seatNumber,bk.booking_status AS bookingStatus,COALESCE((SELECT a.area_name FROM bus_routes r JOIN areas a ON a.area_id=r.area_id WHERE r.bus_id=b.bus_id ORDER BY r.route_order LIMIT 1),'—') AS areaName FROM bookings bk JOIN buses b ON b.bus_id=bk.bus_id WHERE bk.student_id=? ORDER BY bk.booked_at DESC",s.id)));return;}
  if(path.equals("/api/student/bookings")&&method.equals("POST")){if(!role(e,"STUDENT"))return;Sess s=session(e);int bus=num(body(e),"busId",0);try(Connection c=db()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("SELECT capacity,active FROM buses WHERE bus_id=? FOR UPDATE")){p.setInt(1,bus);try(ResultSet r=p.executeQuery()){if(!r.next()||r.getInt("active")!=1)throw new IllegalArgumentException("Bus not available.");int cap=r.getInt("capacity");try(PreparedStatement x=c.prepareStatement("SELECT COUNT(*) FROM bookings WHERE bus_id=? AND booking_status='BOOKED'")){x.setInt(1,bus);try(ResultSet rr=x.executeQuery()){rr.next();if(rr.getInt(1)>=cap)throw new IllegalArgumentException("This bus is full.");}}}}try(PreparedStatement p=c.prepareStatement("SELECT booking_id FROM bookings WHERE student_id=? AND bus_id=? AND booking_status='BOOKED'")){p.setInt(1,s.id);p.setInt(2,bus);try(ResultSet r=p.executeQuery()){if(r.next())throw new IllegalArgumentException("You already booked this bus.");}}int seat=1;try(PreparedStatement p=c.prepareStatement("SELECT seat_number FROM bookings WHERE bus_id=? AND booking_status='BOOKED' ORDER BY seat_number")){p.setInt(1,bus);try(ResultSet r=p.executeQuery()){Set<Integer> used=new HashSet<>();while(r.next())used.add(r.getInt(1));while(used.contains(seat))seat++;}}try(PreparedStatement p=c.prepareStatement("INSERT INTO bookings(student_id,bus_id,seat_number,booking_status,booked_at) VALUES(?,?,?,'BOOKED',NOW())")){p.setInt(1,s.id);p.setInt(2,bus);p.setInt(3,seat);p.executeUpdate();}c.commit();json(e,201,Map.of("message","Seat booked","seatNumber",seat));}catch(Exception ex){c.rollback();throw ex;}}return;}
  if(path.matches("/api/student/bookings/\\d+")&&method.equals("DELETE")){if(!role(e,"STUDENT"))return;Sess s=session(e);int id=Integer.parseInt(path.substring(path.lastIndexOf('/')+1));int n=update("UPDATE bookings SET booking_status='CANCELLED',cancelled_at=NOW() WHERE booking_id=? AND student_id=? AND booking_status='BOOKED'",id,s.id);if(n==0){json(e,404,Map.of("message","Booking not found or already cancelled."));return;}json(e,200,Map.of("message","Booking cancelled"));return;}
  if(path.equals("/api/student/requests")&&method.equals("POST")){if(!role(e,"STUDENT"))return;Sess s=session(e);Map<String,Object>b=body(e);int area=num(b,"areaId",0);if(rows("SELECT area_id FROM areas WHERE area_id=? AND active=1",area).isEmpty()){json(e,400,Map.of("message","Choose a valid area."));return;}int id=insert("INSERT INTO bus_requests(student_id,area_id,request_note,request_status,created_at) VALUES(?,?,?,'PENDING',NOW())",s.id,area,str(b,"requestNote"));json(e,201,Map.of("message","Request submitted","requestId",id));return;}
  if(path.equals("/api/driver/profile")){if(!role(e,"DRIVER"))return;Sess s=session(e);List<Map<String,Object>> a=rows("SELECT driver_id AS driverId,driver_code AS driverCode,full_name AS fullName,email FROM drivers WHERE driver_id=?",s.id);json(e,200,a.isEmpty()?Map.of():a.get(0));return;}
  if(path.equals("/api/driver/bus")){if(!role(e,"DRIVER"))return;Sess s=session(e);List<Map<String,Object>> a=rows("SELECT b.bus_id AS busId,b.bus_number AS busNumber,b.bus_name AS busName,b.capacity,COUNT(DISTINCT CASE WHEN bk.booking_status='BOOKED' THEN bk.booking_id END) AS bookedSeats,b.capacity-COUNT(DISTINCT CASE WHEN bk.booking_status='BOOKED' THEN bk.booking_id END) AS availableSeats,GROUP_CONCAT(DISTINCT ar.area_name ORDER BY br.route_order SEPARATOR ', ') AS routeNames,GROUP_CONCAT(DISTINCT TIME_FORMAT(br.pickup_time,'%H:%i') ORDER BY br.route_order SEPARATOR ', ') AS pickupTimes FROM drivers d LEFT JOIN buses b ON b.bus_id=d.bus_id LEFT JOIN bus_routes br ON br.bus_id=b.bus_id AND br.active=1 LEFT JOIN areas ar ON ar.area_id=br.area_id LEFT JOIN bookings bk ON bk.bus_id=b.bus_id AND bk.booking_status='BOOKED' WHERE d.driver_id=? GROUP BY b.bus_id",s.id);json(e,200,a.isEmpty()?Map.of("bus",Map.of()):Map.of("bus",a.get(0)));return;}
  if(path.equals("/api/driver/passengers")){if(!role(e,"DRIVER"))return;Sess s=session(e);json(e,200,Map.of("items",rows("SELECT st.full_name AS fullName,st.roll_number AS rollNumber,st.email,bk.seat_number AS seatNumber,COALESCE((SELECT a.area_name FROM bus_routes r JOIN areas a ON a.area_id=r.area_id WHERE r.bus_id=b.bus_id ORDER BY r.route_order LIMIT 1),'—') AS areaName FROM drivers d JOIN buses b ON b.bus_id=d.bus_id JOIN bookings bk ON bk.bus_id=b.bus_id AND bk.booking_status='BOOKED' JOIN students st ON st.student_id=bk.student_id WHERE d.driver_id=? ORDER BY bk.seat_number",s.id)));return;}
  if(path.startsWith("/api/admin/")){if(!role(e,"ADMIN"))return;admin(e,path,method);return;}json(e,404,Map.of("message","API endpoint not found: "+path)); }
 static void admin(HttpExchange e,String path,String method)throws Exception{String sub=path.substring("/api/admin/".length());if(sub.equals("summary")){json(e,200,Map.of("students",rows("SELECT COUNT(*) n FROM students").get(0).get("n"),"drivers",rows("SELECT COUNT(*) n FROM drivers").get(0).get("n"),"buses",rows("SELECT COUNT(*) n FROM buses").get(0).get("n"),"pendingRequests",rows("SELECT COUNT(*) n FROM bus_requests WHERE request_status='PENDING'").get(0).get("n")));return;}
  if(sub.equals("students")){if(method.equals("GET")){json(e,200,Map.of("items",rows("SELECT student_id AS studentId,full_name AS fullName,roll_number AS rollNumber,email,active FROM students ORDER BY full_name")));return;}Map<String,Object>b=body(e);if(method.equals("POST")){String pw=str(b,"password");if(pw.isBlank())pw="123@RC";insert("INSERT INTO students(full_name,roll_number,email,password_hash,active) VALUES(?,?,?,?,1)",str(b,"fullName"),str(b,"rollNumber"),str(b,"email").toLowerCase(),hash(pw));json(e,201,Map.of("message","Student created"));return;} }
  if(sub.startsWith("students/")){int id=tailId(sub);Map<String,Object>b=body(e);if(b.containsKey("active")){update("UPDATE students SET active=? WHERE student_id=?",bool(b,"active"),id);}else{if(b.containsKey("password"))update("UPDATE students SET full_name=?,roll_number=?,email=?,password_hash=? WHERE student_id=?",str(b,"fullName"),str(b,"rollNumber"),str(b,"email").toLowerCase(),hash(str(b,"password")),id);else update("UPDATE students SET full_name=?,roll_number=?,email=? WHERE student_id=?",str(b,"fullName"),str(b,"rollNumber"),str(b,"email").toLowerCase(),id);}json(e,200,Map.of("message","Student updated"));return;}
  if(sub.equals("drivers")){if(method.equals("GET")){json(e,200,Map.of("items",rows("SELECT d.driver_id AS driverId,d.full_name AS fullName,d.driver_code AS driverCode,d.email,d.bus_id AS busId,b.bus_number AS busNumber,d.active FROM drivers d LEFT JOIN buses b ON b.bus_id=d.bus_id ORDER BY d.full_name")));return;}Map<String,Object>b=body(e);String pw=str(b,"password");if(pw.isBlank())pw="123@RC";insert("INSERT INTO drivers(full_name,driver_code,email,password_hash,bus_id,active) VALUES(?,?,?,?,?,1)",str(b,"fullName"),str(b,"driverCode"),str(b,"email").toLowerCase(),hash(pw),num(b,"busId",0));json(e,201,Map.of("message","Driver created"));return;}
  if(sub.startsWith("drivers/")){int id=tailId(sub);Map<String,Object>b=body(e);if(b.containsKey("active"))update("UPDATE drivers SET active=? WHERE driver_id=?",bool(b,"active"),id);else if(b.containsKey("password"))update("UPDATE drivers SET full_name=?,driver_code=?,email=?,bus_id=?,password_hash=? WHERE driver_id=?",str(b,"fullName"),str(b,"driverCode"),str(b,"email").toLowerCase(),num(b,"busId",0),hash(str(b,"password")),id);else update("UPDATE drivers SET full_name=?,driver_code=?,email=?,bus_id=? WHERE driver_id=?",str(b,"fullName"),str(b,"driverCode"),str(b,"email").toLowerCase(),num(b,"busId",0),id);json(e,200,Map.of("message","Driver updated"));return;}
  if(sub.equals("buses")){if(method.equals("GET")){json(e,200,Map.of("items",rows("SELECT bus_id AS busId,bus_number AS busNumber,bus_name AS busName,capacity,active FROM buses ORDER BY bus_number")));return;}Map<String,Object>b=body(e);insert("INSERT INTO buses(bus_number,bus_name,capacity,active) VALUES(?,?,?,1)",str(b,"busNumber"),str(b,"busName"),num(b,"capacity",40));json(e,201,Map.of("message","Bus created"));return;}
  if(sub.startsWith("buses/")){int id=tailId(sub);Map<String,Object>b=body(e);if(b.containsKey("active"))update("UPDATE buses SET active=? WHERE bus_id=?",bool(b,"active"),id);else update("UPDATE buses SET bus_number=?,bus_name=?,capacity=? WHERE bus_id=?",str(b,"busNumber"),str(b,"busName"),num(b,"capacity",40),id);json(e,200,Map.of("message","Bus updated"));return;}
  if(sub.equals("routes")){if(method.equals("GET")){json(e,200,Map.of("items",rows("SELECT r.route_id AS routeId,r.bus_id AS busId,r.area_id AS areaId,b.bus_number AS busNumber,a.area_name AS areaName,TIME_FORMAT(r.pickup_time,'%H:%i') AS pickupTime,r.route_order AS routeOrder,r.active FROM bus_routes r JOIN buses b ON b.bus_id=r.bus_id JOIN areas a ON a.area_id=r.area_id ORDER BY b.bus_number,r.route_order")));return;}Map<String,Object>b=body(e);insert("INSERT INTO bus_routes(bus_id,area_id,pickup_time,route_order,active) VALUES(?,?,?, ?,1)",num(b,"busId",0),num(b,"areaId",0),str(b,"pickupTime"),num(b,"routeOrder",1));json(e,201,Map.of("message","Route created"));return;}
  if(sub.startsWith("routes/")){int id=tailId(sub);Map<String,Object>b=body(e);update("UPDATE bus_routes SET bus_id=?,area_id=?,pickup_time=?,route_order=? WHERE route_id=?",num(b,"busId",0),num(b,"areaId",0),str(b,"pickupTime"),num(b,"routeOrder",1),id);json(e,200,Map.of("message","Route updated"));return;}
  if(sub.equals("requests")){json(e,200,Map.of("items",rows("SELECT br.request_id AS requestId,br.area_id AS areaId,a.area_name AS areaName,br.student_id AS studentId,s.full_name AS studentName,br.request_note AS requestNote,br.request_status AS requestStatus,COUNT(*) OVER(PARTITION BY br.area_id) AS requestCount,br.created_at AS createdAt FROM bus_requests br JOIN areas a ON a.area_id=br.area_id JOIN students s ON s.student_id=br.student_id ORDER BY (br.request_status='PENDING') DESC,requestCount DESC,br.created_at DESC")));return;}
  if(sub.startsWith("requests/")&&method.equals("PUT")){int id=tailId(sub);String status=str(body(e),"requestStatus").toUpperCase();if(!Set.of("APPROVED","REJECTED").contains(status)){json(e,400,Map.of("message","Invalid request status"));return;}Sess s=session(e);update("UPDATE bus_requests SET request_status=?,reviewed_by_admin_id=?,reviewed_at=NOW() WHERE request_id=?",status,s.id,id);json(e,200,Map.of("message","Request updated"));return;}json(e,404,Map.of("message","Unknown admin endpoint")); }
 static int tailId(String s){return Integer.parseInt(s.substring(s.lastIndexOf('/')+1));}
 static void staticFile(HttpExchange e)throws IOException{String p=e.getRequestURI().getPath();if(p.equals("/"))p="/home.html";Path f=ROOT.resolve(p.substring(1)).normalize();if(!f.startsWith(ROOT)||!Files.isRegularFile(f)){byte[] b="Not found".getBytes();e.sendResponseHeaders(404,b.length);try(OutputStream o=e.getResponseBody()){o.write(b);}return;}String type=f.toString().endsWith(".html")?"text/html; charset=UTF-8":f.toString().endsWith(".css")?"text/css; charset=UTF-8":f.toString().endsWith(".js")?"application/javascript; charset=UTF-8":f.toString().endsWith(".png")?"image/png":f.toString().endsWith(".jpg")||f.toString().endsWith(".jpeg")?"image/jpeg":"application/octet-stream";e.getResponseHeaders().set("Content-Type",type);e.getResponseHeaders().set("X-Content-Type-Options","nosniff");e.getResponseHeaders().set("Cache-Control","no-cache");byte[] b=Files.readAllBytes(f);e.sendResponseHeaders(200,b.length);try(OutputStream o=e.getResponseBody()){o.write(b);}}
 public static void main(String[] args)throws Exception{Class.forName("com.mysql.cj.jdbc.Driver");try(Connection c=db();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM students")){r.next();System.out.println("MySQL connected. Students: "+r.getInt(1));}HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",8080),0);server.createContext("/api/",e->{try{api(e);}catch(IllegalArgumentException x){try{json(e,400,Map.of("message",x.getMessage()==null?"Invalid request":x.getMessage()));}catch(Exception ignored){}}catch(SQLException x){x.printStackTrace();try{json(e,500,Map.of("message","Database error: "+x.getMessage()));}catch(Exception ignored){}}catch(Exception x){x.printStackTrace();try{json(e,500,Map.of("message","Server error: "+(x.getMessage()==null?x.getClass().getSimpleName():x.getMessage())));}catch(Exception ignored){}}finally{e.close();}});server.createContext("/",e->{try{staticFile(e);}catch(Exception x){try{json(e,500,Map.of("message","Could not serve file"));}catch(Exception ignored){}}finally{e.close();}});server.setExecutor(Executors.newFixedThreadPool(12));server.start();System.out.println("BusMate started: http://localhost:8080");System.out.println("Health check: http://localhost:8080/api/health");}
}
